const jobUsed = j => (P.jobs[j]||{jp:0}).jp > 0 || j === P.job;
const abLearned = r => !!r && jobUsed(r.j) && jobLv(r.j) >= r.a.lv;   // おぼえた アビリティ（マスター 不要）
