const slotCat = k => k.startsWith('x') ? 'any' : k.replace(/\d+$/, '');
function abRef(v){ const [, j, nm] = v.split(':'); const a = JOBS[j] && JOBS[j].ab.find(x=>x.n===nm); return a ? {j, a} : null; }
