Object.assign(JOBS, JOBS2);
for (const j in JOBS2){ JOBS2[j].ab.forEach((a,i)=>a.lv=i+1); VAR('hero_'+j, 'hero', {B: JOBS2[j].col}); JOB_KEYS.push(j); }
const MAIN_JOBS = JOB_KEYS.filter(k => !JOBS[k].abyss && !JOBS[k].special);
const jobOpen = k => !JOBS[k].unlock || JOBS[k].unlock() || (P.jobs[k] && P.jobs[k].jp > 0);

// ===== 武器の 系統（通常攻撃と つかえる ひらめき技が 武器で きまる） =====
