    "..YY..kkYkY",
    "...YYkDDDDD",
    "....kDDDDDD",
    "....kDRRwDD",
    "....kDDRRDD",
    "....kkDDDDm",
    "..kkPPkYYYY",
    ".kPPPPDkYGY",
