// ===== デバッグ: エンドコンテンツから 試す（いまの セーブは 退避して あとで もどせる） =====
const DBG_BAK = SAVE_KEY + '-bak';
function debugSave(R){
  const L = lvOf(5, R), hl = Math.min(999, 25*R);
  const D = freshSave();
  D.debug = R; D.hero.lv = hl; D.gold = 10000000; D.shards = 999; D.uid = 0;
  D.clear = [R,R,R,R,R,R]; D.sel = {st:0, rd:Math.min(MAX_ROUND, R+1)};
  D.stats = {kills:50000, clears:R*6, runs:R*8};
  for(const k of JOB_KEYS) D.jobs[k] = {jp: JOB_T[JOB_MAX-1]};
  for(const k of Object.keys(MATS)) D.mats[k] = 999;
  for(const k of Object.keys(CARDS)){ D.cards[k] = 3; D.album[k] = true; }
  for(const k of Object.keys(FAC)) D.fac[k] = FAC[k].max;
  D.craft = {m:999};
  for(const id of Object.keys(SK)) D.skills[id] = {m:ST_T[ST_T.length-1]};
  for(const u of Object.keys(UNIQ)) D.extracted[u] = true;
  D.seen = Object.assign({}, P.seen||{}, {airTip:1, allyCtrl:1});
  D.tabsOpen = {skill:1, ally:1, gear:1, job:1, card:1, town:1};
  D.opt = Object.assign({}, P.opt||{}, {allyAuto:true});
  // 一時的に P を さしかえて 装備・仲間を つくる
  const keep = P; P = D;
  try{
    const mk = (opt, ref) => { const it = genItem(L, true, true, opt); it.id = ++P.uid; it.ref = ref; refName(it); if(!Array.isArray(it.cards)) it.cards = []; return it; };
    for(const wt of WT) P.inv.push(mk({rar:4, slot:'weapon', wt}, 7));
    for(const sl of SLOTS.filter(s=>s!=='weapon')) P.inv.push(mk({rar:4, slot:sl}, 7));
    for(const u of Object.keys(UNIQ)) P.inv.push(mk({rar:3, u}, 0));
    for(const a of Object.keys(ARTI)){ P.inv.push(mk({rar:5, a}, 7)); P.artFound[a] = 1; }   // 神器も 7本
    for(const k of EQ){ const sl = k==='acc2' ? 'acc' : k; let best = null; for(let n=0;n<12;n++){ const it = mk(k==='weapon' ? {rar:4, slot:'weapon', wt:'sword'} : {rar:4, slot:sl}, 7); if(!best || itemScore(it) > itemScore(best)) best = it; } P.equip[k] = best; }   // 12本 つくって いちばん 強いもの
    // 仲間: 種族ごとに いちばん 上の 種
    for(const fam of Object.keys(FAM)){
      const sp = Object.keys(EDEF).filter(k=>EDEF[k].fam===fam && !EDEF[k].special).sort((a,b)=>(RANK[b]||0)-(RANK[a]||0))[0]; if(!sp) continue;
      const al = newAlly(sp, L); al.maxLv = 999; al.lv = Math.min(999, hl); al.plus = 30; P.allies.push(al);
    }
    P.party = [...P.allies].sort((a,b)=>allyPow(b)-allyPow(a)).slice(0,3).map(a=>a.id);
    // アビリティを 枠に つける・抽出した 力を つける・スキルレベルを ふる
    const used = new Set();
    for(const k of slotKeys()){ const o = msOptions(slotCat(k)).find(o=>!used.has(o.v)); if(o){ P.mslots[k] = o.v; used.add(o.v); } }
    P.pslots = Object.keys(UNIQ).slice(0, powCount());
    let pts = Math.floor(hl/3);
    for(const wt of ['sword', ...WT.filter(w=>w!=='sword')]){ P.wtree[wt] = {};
      for(const nd of wpNodes(wt)){ const r = Math.min(WP_MAX, pts); if(r<=0) break; P.wtree[wt][nd.k] = r; pts -= r; } }
  } finally { P = keep; }
  return D;
}
function debugStart(R){
  try{
    if(!LS.ok()){ P = Object.assign(freshSave(), debugSave(R)); refreshHS(); syncHero(); hideModal(); toCamp(); return; }   // 保存できない 画面: その場で 切りかえ（元には もどせない）
    if(!P.debug) LS.set(DBG_BAK, JSON.stringify(P));   // ふつうの セーブだけ 退避
    LS.set(SAVE_KEY, JSON.stringify(debugSave(R)));
  }catch(e){ alert('失敗: '+e.message); return; }
  _svT && clearTimeout(_svT); _svT = 0; window._noSave = true;   // 再読みこみまでに 上書きしない
  location.reload();
}
function debugRestore(){
  const raw = LS.get(DBG_BAK); if(!raw) return;
  LS.set(SAVE_KEY, raw); LS.del(DBG_BAK);
  _svT && clearTimeout(_svT); _svT = 0; window._noSave = true;
  location.reload();
}
const DEBUG_MENU = false;   // 公開するときは false に する（そのときは URLに ?debug を つけたときだけ 出る）
const debugOn = () => DEBUG_MENU || /debug/.test(location.search + location.hash) || !!P.debug || !!LS.get(DBG_BAK);   // URLに ?debug を つけたときだけ 出す
function panelDebug(){
  if(!debugOn()) return '';
  const bak = !!LS.get(DBG_BAK);
  return `<h3>🛠 デバッグ</h3>
    ${P.debug ? `<p class="hint r3">いまは デバッグ用の セーブ（${P.debug}周目クリア済み）で 遊んでいる。</p>` : ''}
    <p class="hint">エンドコンテンツから 試す：全ステージ クリア済み・全ジョブ マスター・全ひらめき技・最大の 施設・強い 装備と 仲間 つき。いまの セーブは 退避され、あとで もどせる。</p>
    <div class="row" style="flex-wrap:wrap">${[5,10,15,20,30].map(r=>`<button class="btn sm" data-dbg="go" data-r="${r}">${r}周目クリア から</button>`).join('')}</div>
    ${P.debug ? `<label class="toggle"><span>デバッグ：パーティが ダメージを 受けない</span><input type="checkbox" data-dbgopt="dbgGod" ${P.opt.dbgGod?'checked':''}></label>` : ''}
    <div class="row" style="margin-top:6px"><button class="btn sm" data-dbg="ending">🎬 エンディングを 見る</button><button class="btn sm danger" data-dbg="maou">👿 魔王と 戦う</button></div>
    <div class="row" style="margin-top:6px;flex-wrap:wrap">${[99,299,499,999,1999].map(f=>`<button class="btn sm" data-dbg="tower" data-f="${f}">🗼 塔 ${f}階から</button>`).join('')}</div>
    ${bak ? `<div class="row" style="margin-top:6px"><button class="btn sm primary" data-dbg="restore">元の セーブに もどす</button></div>` : ''}`;
}
document.addEventListener('click', ev=>{
  const b = ev.target.closest('[data-dbg]'); if(!b) return;
  if(b.dataset.dbg==='go') showModal(`<h2>デバッグ</h2><p>${b.dataset.r}周目クリア済みの データで はじめる？</p><p class="hint">いまの セーブは 退避される（設定 → デバッグ →「元の セーブに もどす」で もどる）。${P.debug?'<br>いまは デバッグ用の セーブなので、これは 退避せずに 上書きする。':''}</p><div class="opts"><button class="btn" data-m="close">やめる</button><button class="btn danger" data-dbg="go2" data-r="${b.dataset.r}">はじめる</button></div>`);
  else if(b.dataset.dbg==='go2') debugStart(+b.dataset.r);
  else if(b.dataset.dbg==='ending') playEnding(()=>{});
  else if(b.dataset.dbg==='tower') startTower(+b.dataset.f);
  else if(b.dataset.dbg==='maou'){ startStage(5, TOWER_RD); S.dbgBoss = true; S.waveIdx = WAVES; }   // すぐ ボス戦（10周目の 魔界＝魔王）。クリアの 記録は のこさない
  else if(b.dataset.dbg==='restore') showModal(`<h2>元の セーブに もどす？</h2><p class="hint">デバッグ用の データは 消える。</p><div class="opts"><button class="btn" data-m="close">やめる</button><button class="btn primary" data-dbg="restore2">もどす</button></div>`);
  else if(b.dataset.dbg==='restore2') debugRestore();
});
document.addEventListener('change', ev=>{ const k = ev.target.dataset && ev.target.dataset.dbgopt; if(!k) return; P.opt[k] = ev.target.checked; save(); });

// ===== おまけ: バトル速度・精錬+11・無限の塔 =====
// --- バトル速度 ---
const SPD_UNLOCK = [{v:1, rd:0}, {v:1.5, rd:1}, {v:2, rd:3}];   // 魔界を その周回まで クリアで ひらく
const speeds = () => SPD_UNLOCK.filter(s => (P.clear[5]||0) >= s.rd).map(s=>s.v);
const battleSpd = () => { const v = P.opt.spd || 1; return speeds().includes(v) ? v : 1; };
function syncSpdBtn(){ const b = $('#spdBtn'); if(!b) return; const ok = speeds().length > 1; b.hidden = !ok; b.textContent = '×'+battleSpd(); b.classList.toggle('on', battleSpd() > 1); }
{ const br = $('#bhud .brow') || document.querySelector('.brow');
  if(br){ const b = document.createElement('span'); b.className = 'pill'; b.id = 'spdBtn'; b.hidden = true; br.insertBefore(b, $('#pauseBtn'));
    b.addEventListener('click', ()=>{ const l = speeds(), i = l.indexOf(battleSpd()); P.opt.spd = l[(i+1)%l.length]; save(); syncSpdBtn(); buzz && buzz(8); }); } }
// --- 精錬 +11 ---
const REF11_RD = 7;
const refCap = () => (P.clear[5]||0) >= REF11_RD ? 11 : 10;
// --- 無限の塔（1階 ＝ 1ウェーブ。10階ごとに ボス。どこまで 登れるか） ---
const TOWER_RD = 10;
const towerOpen = () => (P.clear[5]||0) >= TOWER_RD;
const towerBest = () => (P.tower && P.tower.best) || 0;   // 最高記録
const towerPeak = () => Math.max(towerBest(), (P.tower && P.tower.peak) || 0);   // これまでの 最高記録（ひらく ものの 条件は こちら）
const towerStarts = () => { const s = [1]; for(let f=11; f<=towerBest()+1; f+=10) s.push(f); return s; };   // 到達した 10階ごとから はじめられる
const towerL = f => towerL2(f);
function startTower(f0){
  const sel = {...P.sel};
  startStage(5, TOWER_RD, true);
  P.sel = sel;
  S.tower = {f0}; S.floor = f0 - 1;
}
function towerWave(){
  S.floor++;
  const f = S.floor, st = (f-1) % STAGES.length, boss = f % 10 === 0;
  S.st = st; S.L = towerL(f); S.bg = STAGES[st].bg;
  S.waveIdx = boss ? WAVES+1 : 1;
  const rdEq = TOWER_RD - 1 + Math.floor(f/12), stg = STAGES[st];
  S.es = [];
  if(!boss){
    const cc = capCount(st, rdEq, S.L, 3);
    const kinds = [...stg.en].sort(()=>Math.random()-.5).slice(0, 3);
    slots(cc.n).forEach((p,i)=>{ const e = makeEnemy(kinds[i%kinds.length], p.x, p.y, false); e.rm = cc.rm; S.es.push(e); });
    S.waveName = '無限の塔 '+f+'階';
    banner(f+'F');
  }else{
    const cc = capCount(st, rdEq, S.L, WAVES, .6);
    S.es.push(makeEnemy(stg.boss, 168, 100, true));
    slots(Math.round(cc.n*1.5)).filter(p=>Math.abs(p.x-168)>16 || Math.abs(p.y-100)>7).slice(0,cc.n).forEach((p,i)=>{ const e = makeEnemy(stg.en[i%stg.en.length], p.x, p.y, false); e.rm = cc.rm; S.es.push(e); });
    S.waveName = f+'階 BOSS '+EDEF[stg.boss].n;
    banner(f+'F BOSS!');
  }
  towerSpecial(f); towerTintEnemies(f);
  applyTraits();
  S.wave = S.es.length; S.wait = false;
  if(HS.pw.lullaby) S.es.forEach(e=>{ e.sleep = 2; e.stun = Math.max(e.stun, 2); });
  updWaveTxt();
}
function towerClear(){
  const f = S.floor;
  P.tower = P.tower || {best:0}; const nb = f > P.tower.best; if(nb) P.tower.best = f; if(f > (P.tower.peak||0)) P.tower.peak = f;
  if(f > 1000 && f % 10 === 0) gainLshard(2 + Math.floor((f-1000)/500));   // 1000階より 上の ボス階で ひかりのかけら
  S.tower.top = f;
  towerMsClear(f);
  if(S.trueClearNow){ S.trueClearNow = false; S.wait = true; setTimeout(()=>showTrueClear(()=>{ if(mode==='battle'){ S.wait=false; endCombo(); spawnWave(); } }), 1200); return; }
  if(f % 10 === 0){ const it = genItem(S.L, true, true); R.items.push({it, r:addInv(it), chest:true}); later(.6, ()=>banner(f+'階 とうは！ 宝箱'));
    // 神器: 50階ごとを はじめて こえたら かならず、ほかの ボス階は 3%
    if(f % 50 === 0 && f > (P.tower.artMs||0)){ P.tower.artMs = f; later(1.4, ()=>gotArt(null)); }
    else if(Math.random() < .03) later(1.4, ()=>gotArt(null)); }
  else if(nb && f > 1) later(.6, ()=>float('最高記録 '+f+'階','tag',150,40));
  const r = .1*(HS.pw.regen2?2:1)*(1+.1*facLv('inn')) + (HS.pw.prayer?.2:0) + (HS.pw.healWave||0)/100;
  S.php = Math.min(S.pmax, S.php + S.pmax*r);
  save();
  setTimeout(()=>{ if(mode!=='battle') return; endCombo(); spawnWave(); }, 1300/battleSpd());
}
function panelTowerCard(){
  if(!towerOpen()) return `<div class="li" style="cursor:default;opacity:.6"><div class="body"><div class="t"><span>🗼 無限の塔</span><span class="hint">🔒</span></div><div class="d">${TOWER_RD}周目の 魔界を クリアで ひらく</div></div></div>`;
  const b = towerBest();
  return `<h3>🗼 無限の塔</h3><p class="hint">1階 ＝ 1ウェーブ。上の 階ほど 敵が 強くなり、10階ごとに ボスと 宝箱。全滅か 撤退まで 登りつづける。到達した 10階ごとから はじめられる。</p>
    <div class="kv"><span><i>最高記録</i>${b}階</span><span><i>${b+1}階の 敵の強さ</i>${towerL(b+1)}</span>${titleOf()?`<span><i>称号</i>${titleOf()}</span>`:''}<span><i>いまの 層</i>${TIERS[tierOf(b+1)].n}</span></div>
    ${(()=>{ const nx = [100,300,500,1000,2000].find(n=>n>b); return (P.tower.trueClear ? '<p class="r5">完全制覇！</p>' : '') + (nx ? `<p class="hint">つぎの 節目：${nx}階 ？？？</p>` : ''); })()}
    <div class="row" style="flex-wrap:wrap;margin-top:6px">${towerStarts().slice(-4).map(f=>`<button class="btn ${f===towerStarts().slice(-1)[0]?'primary':''}" data-act="tower" data-f="${f}">${f}階から</button>`).join('')}</div>`;
}

// ===== 無限の塔の 物語: 節目ボス・景色の 変化・称号 =====
// 2階ごとに 1 強く。100階から 先は 4階ごとに 1
const towerL2 = f => lvOf(5, TOWER_RD) - 6 + (f <= 100 ? Math.ceil(f/2) : 50 + Math.ceil((f-100)/4));
// --- 景色（100階ごとに 塔の 中の 色が かわり、敵も 深層の 色に なる） ---
const TIERS = [
  {n:'塔の 入口', col:null},
  {n:'たそがれの 回廊', col:'#3a2a6a'}, {n:'紅の 層', col:'#7a1a1a'}, {n:'影の 層', col:'#1a1030'},
  {n:'深海の 層', col:'#0a3a4a'}, {n:'雲の 上', col:'#a8c8ff'}, {n:'星の 層', col:'#1a1a4a'},
  {n:'灰の 層', col:'#3a3a3a'}, {n:'黄金の 層', col:'#c8a000'}, {n:'光の 層', col:'#fff6c0'},
  // 1000階より 上（1000階ごとに かわる）
  {n:'混沌の 層', col:'#4a0a3a'}, {n:'星海の 層', col:'#0a1a5a'}, {n:'虚無の 層', col:'#101010'},
];
const tierOf = f => { f = Math.max(1, f); return f <= 1000 ? Math.floor((f-1)/100) : Math.min(TIERS.length-1, 10 + Math.floor((f-1001)/1000)); };
function towerTint(){
  if(!S.tower || mode!=='battle') return;
  const t = TIERS[tierOf(S.floor)]; if(!t.col) return;
  ctx.globalAlpha = .28; ctx.fillStyle = t.col; ctx.fillRect(-W, -H, W*3, H*3); ctx.globalAlpha = 1;
}
// --- 称号 ---
const TITLES = [[10,'塔の 見習い'],[50,'塔の 冒険者'],[100,'守護者を こえし者'],[200,'雲を ぬける者'],[300,'影を はらう者'],[500,'頂を 知る者'],[700,'天を 衝く者'],[1000,'ひらめきの 勇者'],
  [1500,'光を 継ぐ者'],[2000,'混沌を しずめし者'],[3000,'星海を 渡る者'],[5000,'伝説の ひらめき'],[10000,'ピコーンの 神']];
const titleOf = (b = towerPeak()) => { let t = ''; for(const [f,n] of TITLES) if(b >= f) t = n; return t; };
// --- 節目の ボス ---
const TMS = {
  100: {key:'b_guard', hp:1.5, intro:['……ここより 上は、神器を もつに ふさわしい ものだけが 進める。', 'わが 試練を うけよ。'], name:'神器の守護者'},
  300: {key:'b_shadow', hp:2.5, intro:['……ヴァルゴスの 闇は、まだ 消えては いない。', 'われは 魔王の 影。この 塔の 闇そのもの。'], name:'魔王の影'},
  2000:{key:'b_chaos', hp:6, intro:['……ふふ、ふふふ。ひかりが まぶしくて ねむれやしない。', 'われは ヴァルピコ。魔王の 闇と ひらめきの 光が まざって うまれた もの。', 'おまえの ひらめきも、まるごと のみこんで やろう！'], name:'混沌の源 ヴァルピコ'},
  1000:{key:'b_source', hp:4, intro:['……よくぞ ここまで のぼってきた。', 'この 塔の 光は、もう 消えかけている。', 'さあ、見せてくれ。おまえの ひらめきの 光を！'], name:'ひらめきの源'},
};
function towerSpecial(f){
  P.tower.ms = P.tower.ms || {};
  // 500階: 塔の 頂の 扉（はじめて とどいた ときだけ）
  if(f === 500 && !P.tower.ms.e500){ P.tower.ms.e500 = 1; save();
    later(.2, ()=>sayLines('？？？', 'bulb', ['……ここまで きた ものは、ひさしぶりだ。', 'この 塔は、わたしが つくった。ひらめきの 光を もつ ものを さがすために。', 'わたしは「ひらめきの源」。すべての ピコーンは、わたしから 生まれた。', '……だが、わたしの 光は 消えかけている。', '1000階で まっている。'])); }
  const ms = TMS[f]; if(!ms) return;
  // ボスを 入れかえ
  const old = S.es.find(e=>e.boss); if(old) S.es = S.es.filter(e=>e!==old);
  const e = makeEnemy(ms.key, 168, 100, true);
  e.hp = e.max = Math.round(e.max*ms.hp); e.name = ms.name; e.ms = f;
  if(f === 100){ e.s = 3.4; e.aura = '#ffe14a'; }
  if(f === 300){ e.s = 2.6; e.dark = true; e.fast = true; e.mAtk = 0; e.aura = '#6a4ab0';
    e.cfg = {name:ms.name, p2lines:['……かげは、ひとつでは ない。'], p2banner:'影分身！', spawn:['b_shadow','b_shadow'], spawnHp:.15, spawnName:'影の 分身'}; }
  if(f === 2000){ e.s = 3.6; e.dark = true; e.mAtk = 0; e.aura = '#9a4ae0'; e.atk *= 1.2;
    e.cfg = {name:ms.name, p2key:'b_chaos2', p2lines:['……ひかりと やみが、ひっくりかえる……！', 'これが 混沌の ほんとうの 姿だ！'], p2banner:'光と 闇が 反転した！', spawn:['b_shadow','b_guard'], spawnHp:.08, spawnName:'まぼろし'}; }
  if(f === 1000){ e.s = 4; e.dark = true; e.mAtk = 0; e.aura = '#fff6c0';
    e.cfg = {name:ms.name, p2key:'b_source2', p2lines:['……ああ、あたたかい。', 'だが まだだ！ もっと 強い 光を！'], p2banner:'ひらめきの源が かがやいた！', spawn:['h_slime','s_slime','b_kslime']}; }
  S.es.push(e);
  S.waveName = f+'階 '+ms.name;
  later(.3, ()=>sayLines(ms.name, ms.key, ms.intro));
}
// 深層の 色
function towerTintEnemies(f){ const t = TIERS[tierOf(f)]; if(!t.col) return; for(const e of S.es) if(!e.ms) e.tint = t.col; }
// 節目を はじめて こえたとき
function towerMsClear(f){
  if([10,50,100,200,300,500,1000,1500,2000,3000,5000,10000].includes(f) && towerPeak() <= f) track('tw'+f, '無限の塔 '+f+'階');
  P.tower.ms = P.tower.ms || {};
  const nt = TITLES.find(([n])=>n===f); if(nt && !(P.tower.titles||{})[f]){ P.tower.titles = P.tower.titles || {}; P.tower.titles[f] = 1; later(1.2, ()=>toast(`称号「${nt[1]}」を 手に入れた！`)); }
  if(f > 1 && tierOf(f) !== tierOf(f-1)) later(.2, ()=>banner(TIERS[tierOf(f)].n));
  if(!TMS[f] || P.tower.ms[f]) return;
  P.tower.ms[f] = 1; save();
  if(f === 100){ later(.8, ()=>artChoice()); }
  if(f === 300){ later(.8, ()=>{ const L = S.L, it = genItem(L, true, true, {rar:3, ilv:3*L+8}); it.name = '伝説の '+it.name; it.legend = true; R.items.push({it, r:addInv(it), chest:true}); banner('伝説の 装備を 手に入れた！'); }); }
  if(f === 1000){ P.tower.trueClear = Date.now(); track('trueclear', '完全制覇'); save(); S.trueClearNow = true;
    whenFree(()=>toast('1000階で ひらいた：技の「極」・神器の 強化・光のゆうしゃ（設定 → あそびかた）')); }
  if(f === 2000){ later(.8, ()=>{ const L = S.L, it = genItem(L, true, true, {rar:3, ilv:3*L+12}); it.name = '混沌の '+it.name; it.legend = true; R.items.push({it, r:addInv(it), chest:true});
    gainLshard(20); banner('混沌を しずめた！'); whenFree(()=>toast('「闇のゆうしゃ」の 姿が ひらいた！（設定 → ゆうしゃの 見た目）')); }); }
}
// 神器を ひとつ えらぶ（100階の 守護者）
function artChoice(){
  const miss = Object.keys(ARTI).filter(k=>!(P.artFound||{})[k]), ks = miss.length ? miss : Object.keys(ARTI);
  showModal(`<h2 class="r5">神器を ひとつ えらぶ</h2><p class="hint">守護者の 試練を こえた あかしに、神器を ひとつ さずけられる。</p>
    <div class="list">${ks.map(k=>`<button class="li" data-m="artPick" data-k="${k}"><div class="body"><div class="t"><span class="r5">${ARTI[k].n}</span><span class="hint">${WT_N[ARTI[k].wt]}</span></div><div class="d">${ARTI[k].p}</div></div></button>`).join('')}</div>`);
}
$('#modal').addEventListener('click', ev=>{ const b = ev.target.closest('[data-m="artPick"]'); if(!b) return;
  hideModal(); const k = b.dataset.k, it = genItem(S.L, true, true, {rar:5, a:k}); P.artFound = P.artFound || {}; P.artFound[k] = 1; it.lock = true; P.inv.push(it); R.items.push({it, r:'ok', chest:true});
  flash(); try{ SFX.spark(); }catch(_){} banner('神器を 手に入れた！'); save(); });
// 1000階: 完全制覇
function showTrueClear(done){
  sayLines('ひらめきの源', 'b_source2', ['……ありがとう。おまえの 光で、わたしは また かがやける。', 'ひらめきは、あきらめない ものの もとに やってくる。', 'これからも、たくさん ピコーンと ひらめいて おくれ。'], ()=>{
    let el = document.getElementById('ending'); if(!el){ el = document.createElement('div'); el.id = 'ending'; document.body.appendChild(el); }
    el.hidden = false; el.className = 'on';
    el.innerHTML = `<div class="ed-after"><p class="ed-end">完全制覇</p>
      <div class="ed-hero">${imgTag(heroSpr(),'','width:56px;height:auto;image-rendering:pixelated')}　${imgTag('b_source2','','width:56px;height:auto;image-rendering:pixelated')}</div>
      <p class="ed-teaser">無限の塔 1000階を こえ、<br>ひらめきの源に 光を とりもどした。</p>
      <p class="r5 ed-big">称号「${titleOf()}」</p>
      <p class="hint" style="color:#aaa">ゆうしゃ Lv${fmt(P.hero.lv)} ／ 仲間 ${P.allies.length}体 ／ たおした 魔物 ${fmt(P.stats.kills||0)}体</p>
      <div class="row" style="justify-content:center;gap:8px"><button class="btn" data-share="trueClear">𝕏 シェア</button><button class="btn primary" id="tcClose">つづける</button></div></div>`;
    el.querySelector('#tcClose').onclick = () => { el.hidden = true; el.className = ''; el.innerHTML = ''; done && done(); };
  });
}

// ===== 1000階より 先の おたのしみ: ひかりのかけら・神器の 強化・技の 極・ゆうしゃの 見た目・拠点の 飾り =====
// --- ひかりのかけら（1000階より 上で だけ 手に入る） ---
function gainLshard(n){ if(!n) return; P.lshard = (P.lshard||0) + n; if(R){ R.mats = R.mats || {}; R.mats.lshard = (R.mats.lshard||0) + n; } }
// --- 神器の 強化（種類ごとに ✦0〜✦10。抽出した 力にも 効く） ---
const ART_MAX = 10;
const artLv = k => (P.artLv && P.artLv[k]) || 0;
const artMul = k => 1 + .2*artLv(k);                 // 神器の 力の 威力 +20%/段
const artUpOpen = () => towerPeak() >= 1000;
const artUpCost = k => { const n = artLv(k) + 1; return {sh: 3*n, g: 2e6*n}; };
function artUp(k){
  if(!artUpOpen() || artLv(k) >= ART_MAX) return false;
  const c = artUpCost(k); if((P.lshard||0) < c.sh || P.gold < c.g) return false;
  P.lshard -= c.sh; P.gold -= c.g; P.artLv = P.artLv || {}; P.artLv[k] = artLv(k) + 1; save(); return true;
}
function artUpModal(k, back){
  const lv = artLv(k), c = artUpCost(k), mx = lv >= ART_MAX, ok = !mx && (P.lshard||0) >= c.sh && P.gold >= c.g;
  showModal(`<h2 class="r5">神器の 強化</h2><p><b class="r5">${ARTI[k].n}</b>　✦${lv}${mx ? '（最大）' : ` → <b class="r3">✦${lv+1}</b>`}</p>
    <p class="hint">${ARTI[k].p}<br>強化すると この 神器の 力の 威力が 1段 ごとに +20%（いま +${20*lv}%）。抽出した 力にも 効く。</p>
    ${mx ? '' : `<p style="font-size:13px;line-height:1.8">ひつような もの<br>・ひかりのかけら ×${c.sh}（いま ${fmt(P.lshard||0)}）<br>・${fmt(c.g)}G（いま ${fmt(P.gold)}G）</p>`}
    <p class="hint">ひかりのかけらは 無限の塔 1000階より 上の 魔物と ボス階で 手に入る。</p>
    <div class="opts"><button class="btn" data-m="${back ? 'au-back' : 'close'}" data-id="${back||''}">もどる</button>${mx ? '' : `<button class="btn primary" data-m="au-do" data-k="${k}" data-id="${back||''}" ${ok?'':'disabled'}>${ok ? '強化する' : 'たりない'}</button>`}</div>`);
}
$('#modal').addEventListener('click', ev=>{
  const b = ev.target.closest('[data-m]'); if(!b) return; const m = b.dataset.m;
  if(m === 'au-open') artUpModal(b.dataset.k, b.dataset.id);
  else if(m === 'au-do'){ const k = b.dataset.k; if(artUp(k)){ flash(); SFX.lvup(); refreshHS(); artUpModal(k, b.dataset.id); if(mode==='camp') renderCamp(); } }
  else if(m === 'au-back'){ const id = +b.dataset.id; if(id) itemModal(id); else hideModal(); }
});
// --- 技の 極（★5の 先。1000階に とどくと ひらく） ---
const kiwamiOpen = () => towerPeak() >= 1000;
// --- ゆうしゃの 見た目（光: 1000階、闇: 2000階） ---
const SKINS = [{k:'', n:'ふつう', f:0}, {k:'L', n:'光のゆうしゃ', f:1000}, {k:'D', n:'闇のゆうしゃ', f:2000}];
const skinOpen = k => { const s = SKINS.find(x=>x.k===k); return !!s && towerPeak() >= s.f; };
{ const mix = (a, b, t) => { const p = h => [1,3,5].map(i=>parseInt(h.slice(i,i+2),16)), A = p(a), B = p(b); return '#'+A.map((v,i)=>Math.round(v+(B[i]-v)*t).toString(16).padStart(2,'0')).join(''); };
  for(const j of JOB_KEYS){ const base = SPR['hero_'+j]; if(!base) continue; const B = base.pal.B || '#2f64cc';
    VAR('hero_'+j+'_L', 'hero_'+j, {B: mix(B, '#fff6c0', .55), H:'#f2c23e', P:'#fff0c8', k:'#8a6a20', Y:'#ffffff', s:'#fff0d8', g:'#ffffff'});
    VAR('hero_'+j+'_D', 'hero_'+j, {B: mix(B, '#1a0a20', .6), H:'#2a1440', P:'#1a0a20', k:'#000000', e:'#ff3a3a', Y:'#c8324a', s:'#d8c0d8', g:'#9a4ae0'}); } }
// --- 拠点の 飾り（塔の 記録で ふえる） ---
function campTrophies(){
  const b = towerPeak(); if(!b) return; const t = S.time;
  if(b >= 100){   // テントの 上に 金の 旗
    const fx = 163, fy = 50, wv = Math.round(Math.sin(t*4)*1);
    ctx.fillStyle = '#5a3a22'; ctx.fillRect(fx-1, fy, 1, 9);
    ctx.fillStyle = '#f2c23e'; ctx.fillRect(fx, fy, 6, 2); ctx.fillRect(fx, fy+2, 5+wv, 2); ctx.fillStyle = '#c89a20'; ctx.fillRect(fx, fy+4, 3, 1);
  }
  if(b >= 300){   // 紫の ランタン
    const al = .55 + .25*Math.sin(t*3); ctx.fillStyle = 'rgba(154,74,224,'+(al*.35)+')'; ctx.beginPath(); ctx.arc(131, 78, 6, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle = '#3a2a4a'; ctx.fillRect(130, 72, 3, 1); ctx.fillStyle = '#c8a0ff'; ctx.fillRect(129, 74, 5, 6); ctx.fillStyle = '#ffffff'; ctx.fillRect(130, 76, 1, 2);
  }
  if(b >= 500){   // 塔の 模型
    const x = 121, y = 62;
    ctx.fillStyle = '#5a5a6a'; ctx.fillRect(x, y+6, 8, 26); ctx.fillStyle = '#7a7a8a'; ctx.fillRect(x+1, y+6, 3, 26);
    ctx.fillStyle = '#4a4a5a'; for(let k=0;k<4;k++) ctx.fillRect(x+2, y+10+k*6, 4, 2);
    ctx.fillStyle = '#6a6a7a'; ctx.fillRect(x-1, y+4, 10, 2); ctx.fillRect(x+1, y+1, 6, 3);
  }
  if(b >= 1000){   // 塔の てっぺんに 光る 電球
    const al = .5 + .5*Math.sin(t*2.5);
    ctx.fillStyle = 'rgba(255,240,140,'+(.25+.25*al)+')'; ctx.beginPath(); ctx.arc(125, 60, 6+2*al, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle = '#ffe14a'; ctx.fillRect(123, 57, 4, 4); ctx.fillStyle = '#ffffff'; ctx.fillRect(124, 58, 1, 1); ctx.fillStyle = '#a8a8b0'; ctx.fillRect(124, 61, 2, 1);
  }
  if(b >= 2000){   // 光と 闇の 粒が 塔の まわりを まわる
    for(let k=0;k<6;k++){ const a = t*1.6 + k*Math.PI/3; ctx.fillStyle = k%2 ? '#9a4ae0' : '#ffe14a'; ctx.fillRect(Math.round(125 + Math.cos(a)*9), Math.round(76 + Math.sin(a)*4 - k*3), 1, 1); }
  }
  if(b >= 3000){   // 空に 星
    for(let k=0;k<8;k++){ const al = Math.max(0, Math.sin(t*1.3 + k*1.9)); if(al < .3) continue; ctx.globalAlpha = al; ctx.fillStyle = '#fff6c0';
      const x = 10 + ((k*37) % 180), y = 6 + ((k*13) % 24); ctx.fillRect(x, y, 1, 1); if(al > .85){ ctx.fillRect(x-1, y, 3, 1); ctx.fillRect(x, y-1, 1, 3); } } ctx.globalAlpha = 1;
  }
  if(b >= 5000){   // 花火
    const ph = (t % 4)/4, cx = 40 + 120*((Math.floor(t/4)*0.37) % 1), cy = 22;
    if(ph < .6){ const r = ph*30; ctx.globalAlpha = 1 - ph/.6; for(let k=0;k<12;k++){ const a = k*Math.PI/6; ctx.fillStyle = ['#ffe14a','#ff6ad5','#6ad5ff'][k%3]; ctx.fillRect(Math.round(cx+Math.cos(a)*r), Math.round(cy+Math.sin(a)*r*.7), 1, 1); } ctx.globalAlpha = 1; }
  }
}

// ページの スクロール位置（投稿サイトでは #app の 中で スクロールする）
const scrBox = () => document.documentElement.classList.contains('boxed') ? document.getElementById('app') : null;
const scrY = () => { const b = scrBox(); return b ? b.scrollTop : window.scrollY; };
const scrTo = y => { const b = scrBox(); if(b) b.scrollTop = y; else window.scrollTo(0, y); };
// ===== 技の お試し（拠点から 技の 動きを 見る。倒れない 的に うつだけで、経験値・熟練度は ふえない） =====
// 覚えた 技の 並び（スキルタブと 同じ 順）
const demoIds = () => TREES.flatMap(t => Object.keys(SK).filter(k => SK[k].tree===t && P.skills[k]));
let _demoScroll = 0;
function startArtDemo(k){ if(ARTI[k]) demoBegin({art:k}); }
function startDemo(id){ if(SK[id] && P.skills[id]) demoBegin({id}); }
const demoName = () => S.demo.art ? ARTI[S.demo.art].n : SK[S.demo.id].n;
function demoBegin(d){
  if(mode==='battle' && S.demo){ S.demo = d; demoBar(); demoPlay(); return; }   // お試し中は そのまま 切りかえ
  _demoScroll = scrY();
  R = {exp:0, gold:0, jp:0, items:[], lv0:P.hero.lv, job:P.job, jl0:jobLv(P.job), learned:[], sparks:[], recruits:[], charm:{}, mats:{}, cards:[], boxes:0};
  refreshHS(); syncHero(); buildParty(); renderButtons();
  const auto = S.auto;
  S = newBattle(); S.auto = auto; S.solo = soloMode(); S.demo = d;
  S.st = 0; S.rd = 1; S.L = 1; S.bg = 'grass'; S.traits = [];
  S.pmax = partyMaxHp(); S.php = S.pmax;
  PARTS.length=0; FX.length=0; PROJ.length=0;
  ACT.forEach(a=>{ a.anim=null; a.x=a.c.hx; a.y=a.c.hy; });
  mode = 'battle';
  $('#battleUI').hidden=false; $('#camp').hidden=true; $('#bhud').hidden=false; $('#camptag').hidden=true;
  $('#battleUI').classList.add('demo');
  for(const k in _dom) delete _dom[k];
  hideModal(); measureK(); tip('');
  demoBar();
  demoSpawn();
  setTimeout(()=>{ if(S.demo) demoPlay(); }, 500);
}
function demoSpawn(){
  S.es = []; S.waveIdx = 1;
  const kinds = ['slime','bat','goblin'];
  slots(7).forEach((p,i)=>{ const e = makeEnemy(kinds[i%3], p.x, p.y, false); e.hp = e.max = 1e12; e.t = 1e9; e.dummy = true; e.ly = 0; e.vly = 0; e.landed = true; S.es.push(e); });   // 落ちてくる 演出なしで 立たせる
  S.wave = S.es.length; S.wait = false; S.waveName = 'お試し：'+demoName();
}
function demoPlay(){
  if(!S.demo || mode!=='battle') return;
  ACT[0].anim = null; ACT[0].x = ACT[0].c.hx; ACT[0].y = ACT[0].c.hy;
  demoSpawn(); endCombo(); ARTFX.length = 0;
  if(S.demo.art){   // 神器: 通常攻撃を 4回（効果が 出やすいように 確率を 上げる）
    const k = S.demo.art, tok = S.demo;
    for(let j=0;j<4;j++) later(j*.6, ()=>{ if(S.demo!==tok) return; S.cd[0]=0; S.lock=0; S.artCd={}; const r=Math.random; Math.random=()=>0; try{ attack(0,true); } finally{ Math.random=r; } });
    return;
  }
  execSkill(S.demo.id, true, false);
}
function demoBar(){
  let el = $('#demoBar');
  if(!el){ el = document.createElement('div'); el.id = 'demoBar'; $('#battleUI').prepend(el);
    el.addEventListener('click', ev=>{ const b = ev.target.closest('[data-demo]'); if(!b) return;
      const d = b.dataset.demo;
      if(d==='again') demoPlay();
      else if((d==='prev' || d==='next') && !S.demo.art){ const l = demoIds(), i = l.indexOf(S.demo.id); startDemo(l[(i + (d==='next'?1:-1) + l.length) % l.length]); }
      else if(d==='pick') startDemo(b.dataset.id);
      else if(d==='pickA') startArtDemo(b.dataset.id);
      else demoEnd(); }); }
  if(S.demo.art){
    const k = S.demo.art, A = ARTI[k], ks = Object.keys(ARTI).filter(x=>(P.artFound||{})[x]);
    el.innerHTML = `<div class="li sel" style="cursor:default"><div class="body"><div class="t"><span class="r5">▶ ${A.n}</span><span class="hint">神器・${WT_N[A.wt]}</span></div>
      <div class="d">${tagsHtml(ARTI_TAGS[k],true)} ${A.p}</div><p class="hint" style="margin:4px 0 0">お試しなので 効果が かならず 出る。敵は 倒れない。</p></div></div>
      <div class="opts"><button class="btn primary" data-demo="again">もう一度</button></div>
      ${ks.length>1 ? `<div class="chips" style="margin-top:8px">${ks.map(x=>`<button class="chip ${x===k?'on':''}" data-demo="pickA" data-id="${x}">${ARTI[x].n}</button>`).join('')}</div>` : ''}
      <div class="opts" style="margin-top:8px"><button class="btn" data-demo="end">もどる</button></div>`;
    S.waveName = 'お試し：'+A.n; return;
  }
  const id = S.demo.id, sk = SK[id];
  el.innerHTML = `<div class="li sel" style="cursor:default"><div class="body"><div class="t"><span>▶ ${sk.n}</span><span class="r2" style="font-size:11px">${stars(stageOf(P.skills[id].m))}</span></div>
    <div class="d">${tagsHtml(SK_TAGS[id],true)} ${sk.d} ／ ${WT_N[skillWT(id)]}の技 ／ 再使用 ${sk.cd}秒</div>
    <p class="hint" style="margin:4px 0 0">お試しなので 敵は 倒れず、熟練度も ふえない。</p></div></div>
    <div class="opts"><button class="btn" data-demo="prev">◀ 前の技</button><button class="btn primary" data-demo="again">もう一度</button><button class="btn" data-demo="next">次の技 ▶</button></div>
    <div class="chips" style="margin-top:8px">${demoIds().map(k=>`<button class="chip ${k===id?'on':''}" data-demo="pick" data-id="${k}">${SK[k].n}</button>`).join('')}</div>
    <div class="opts" style="margin-top:8px"><button class="btn" data-demo="end">スキルタブに もどる</button></div>`;
  S.waveName = 'お試し：'+sk.n;
}
function demoEnd(){
  $('#battleUI').classList.remove('demo');
  const tab = TAB; toCamp(); TAB = tab; renderCamp();
  requestAnimationFrame(()=>scrTo(_demoScroll));   // 見る前の 位置に もどす
}

// ===== 特典の 一覧（なにで ひらくか・どこまで 進んだか） =====
// ネタバレを ふせる ことば（まだ 見ていない ものは ？？？）
function veilWords(){
  const m = [];
  for(let st=5; st>=1; st--) if(!((P.clear[st-1]||0) >= 1 || (P.clear[st]||0) >= 1)) m.push(STAGES[st].n);
  if(!towerOpen()) m.push('無限の塔');
  if(!Object.keys(P.artFound||{}).length) m.push('神器');
  if((P.clear[5]||0) < TOWER_RD-1) m.push('魔王');
  if(!jobOpen('suppin')) m.push('すっぴん');
  if(refCap() < 11) m.push('+11');
  if(!allyCtrlOpen()) m.push('仲間も 自分で 操作', 'かくし連携');
  return m;
}
const veil = s => { if(!s) return s; for(const w of veilWords()) s = s.split(w).join('？？？'); return s; };
const pg = (cur, need, t) => ({r: Math.max(0, Math.min(1, cur/need)), t: t || `${fmt(Math.min(cur,need))} / ${fmt(need)}`});
const pgAll = (...ps) => ({r: ps.reduce((a,p)=>a+p.r,0)/ps.length, t: ps.map(p=>p.t).join('　')});
const stClear = (st, rd) => pg(clearedRd(st) >= rd ? 1 : 0, 1, clearedRd(st) >= rd ? 'クリア済み' : `${STAGES[st].n} ${rd}周目 未クリア`);
const JOB_PROG = {
  mahouken: () => pgAll(pg(jobLv('senshi'),5,`戦士Lv ${Math.min(5,jobLv('senshi'))}/5`), pg(jobLv('mahou'),5,`魔法使いLv ${Math.min(5,jobLv('mahou'))}/5`)),
  ryuukishi:() => stClear(3,1),
  shoukan:  () => pg(P.stats.recruits||0, 15, `仲間 ${Math.min(15,P.stats.recruits||0)}/15体`),
  jikuu:    () => pg(Object.keys(P.skills).length, 6, `ひらめき技 ${Math.min(6,Object.keys(P.skills).length)}/6`),
  ginyuu:   () => pgAll(pg(jobLv('souryo'),5,`僧侶Lv ${Math.min(5,jobLv('souryo'))}/5`), pg(P.stats.recruits||0,10,`仲間 ${Math.min(10,P.stats.recruits||0)}/10体`)),
  akindo:   () => { const n=(P.stats2.mktSold||0)+(P.stats2.stallSold||0); return pg(n,10,`市場で 売った ${Math.min(10,n)}/10回`); },
  asobi:    () => stClear(5,1),
  kenja:    () => pg(jobLv('asobi'), JOB_MAX, `遊び人Lv ${jobLv('asobi')}/${JOB_MAX}`),
  mamono:   () => stClear(1,2), ninja: () => stClear(2,2), odori: () => stClear(3,2), samurai: () => stClear(4,2), abyssk: () => stClear(5,2),
  suppin:   () => { const n=MAIN_JOBS.filter(k=>jobLv(k)>=JOB_MAX).length; return pg(n, MAIN_JOBS.length, `マスター ${n}/${MAIN_JOBS.length}`); },
};
function perkList(){
  const L = [];
  const add = (cat, n, d, done, p) => L.push({cat, n, d, done:!!done, p: done ? {r:1, t:'達成'} : p});
  // ひらめき技の 枠
  SKILL_UNLOCK.forEach((u,k)=>{ if(!u) return; add('ゆうしゃ', `ひらめき技の 枠 ${k+1}つめ`, `${STAGES[u.st].n}（1周目）を クリア`, (P.clear[u.st]||0)>=1, stClear(u.st,1)); });
  add('ゆうしゃ', allyCtrlOpen() ? '仲間も 自分で 操作 ＋ かくし連携' : '？？？', `${CTRL_ROUND}周目の 魔界を クリア`, allyCtrlOpen(), pg(P.clear[5]||0, CTRL_ROUND, `魔界 ${Math.min(CTRL_ROUND,P.clear[5]||0)}/${CTRL_ROUND}周目`));
  // アビリティの 自由枠
  for(let k=1;k<=4;k++){ const need=3*k, m=mastersCount(); add('ゆうしゃ', `アビリティの 自由枠 ${k}つめ`, `ジョブを ${need}つ マスター`, m>=need, pg(m, need, `マスター ${Math.min(need,m)}/${need}`)); }
  // ジョブ
  for(const k of JOB_KEYS){ const J=JOBS[k]; if(!J.unlock) continue;
    add('ジョブ', J.abyss && !jobOpen(k) ? '？？？' : `${J.n}`, J.hint||'', jobOpen(k), (JOB_PROG[k]||(()=>pg(0,1,'')))()); }
  // 周回
  for(let rd=2; rd<=10; rd++){ const t = traitsOf(rd)[0]; const cl = P.clear[5]||0;
    const seen = cl >= rd-1;
    add('周回', `${rd}周目：${seen ? TRAITS[t].n : '？？？'}`, seen ? TRAITS[t].d + (t==='maou' ? '（倒すと 伝説の 装備）' : '') : 'どんな 周回かは とどいてからの おたのしみ', seen, pg(cl, rd-1, `魔界 ${Math.min(rd-1,cl)}/${rd-1}周目 クリア`)); }
  { const cl = P.clear[5]||0; add('周回', cl>=10 ? '11周目〜：特色が 2つ 重なる' : '11周目〜：？？？', cl>=10 ? '周回ごとに ちがう 組み合わせ' : 'とどいてからの おたのしみ', cl>=10, pg(cl, 10, `魔界 ${Math.min(10,cl)}/10周目 クリア`)); }
  // おまけ
  { const cl = P.clear[5]||0;
    for(const s of SPD_UNLOCK.filter(s=>s.rd>0)) add('おまけ', `バトル速度 ×${s.v}`, `${s.rd}周目の 魔界を クリア（戦闘画面の 速度ボタン）`, cl>=s.rd, pg(cl, s.rd, `魔界 ${Math.min(s.rd,cl)}/${s.rd}周目 クリア`));
    add('おまけ', '精錬 +11', `${REF11_RD}周目の 魔界を クリア（+11で 基本性能 15倍。成功率 5%）`, cl>=REF11_RD, pg(cl, REF11_RD, `魔界 ${Math.min(REF11_RD,cl)}/${REF11_RD}周目 クリア`));
    add('おまけ', '無限の塔', `${TOWER_RD}周目の 魔界を クリア（出撃ページに あらわれる）`, towerOpen(), pg(cl, TOWER_RD, `魔界 ${Math.min(TOWER_RD,cl)}/${TOWER_RD}周目 クリア`));
  }
  // 仲間の 限界突破（塔の 節目）
  for(const [f, cap] of BRK_TIERS) add('おまけ', towerOpen() ? `仲間の 限界突破（上限 Lv${cap >= 9999 ? '9999' : cap}まで）` : '？？？', `無限の塔 ${f}階に とどく（仲間の 画面で 上限を +50ずつ）`, towerPeak() >= f, pg(Math.min(f, towerPeak()), f, `${Math.min(f, towerPeak())}/${f}階`));
  // 1000階より 先
  { const op = towerOpen(), pk = towerPeak(), T = (f, n, d) => add('おまけ', op && pk >= f*.5 ? n : '？？？', op && pk >= f*.5 ? d : `無限の塔 ${f}階`, pk >= f, pg(Math.min(f, pk), f, `${Math.min(f, pk)}/${f}階`));
    T(1000, '技の 極 ／ 神器の 強化 ／ 光のゆうしゃ', '無限の塔 1000階に とどく');
    T(2000, '闇のゆうしゃ ／ ' + (pk >= 2000 ? '混沌の源' : '？？？'), '無限の塔 2000階を こえる');
    for(const [f, n] of TITLES.filter(([f])=>f > 1000)) add('おまけ', op && pk >= 1000 ? `称号「${n}」` : '？？？', `無限の塔 ${f}階`, pk >= f, pg(Math.min(f, pk), f, `${Math.min(f, pk)}/${f}階`)); }
  // 神器
  { const n = Object.keys(P.artFound||{}).length, all = Object.keys(ARTI).length;
    add('あつめる', `神器 コレクション`, '7本 そろえると 神器の力の枠が 2つに なる（無限の塔の 50階ごと・ボス階、11周目からの 魔界ボスで 手に入る）', n>=all, pg(n, all, `${n}/${all}本`)); }
  // カード・施設
  { const n = albumCount(), all = Object.keys(CARDS).length; add('あつめる', 'カード帖 コンプリート', 'ひらめき率 +20%', n>=all, pg(n, all, `${n}/${all}まい`)); }
  for(const lv of [3,5]){ const f = facLv('forge'); add('あつめる', `抽出した 力の 枠 +${lv===3?1:2}`, `町の 施設「工房」を Lv${lv}に`, f>=lv, pg(f, lv, `工房 Lv${Math.min(lv,f)}/${lv}`)); }
  return L;
}
function panelPerks(){
  const L = perkList(), done = L.filter(x=>x.done).length;
  const cats = [...new Set(L.map(x=>x.cat))];
  let h = (P.seen && P.seen.ending ? `<div class="row" style="margin-bottom:6px"><button class="btn sm" data-act="ending">🎬 エンディングを 見なおす</button></div>` : '') + `<div class="kv"><span><i>特典</i>${done} / ${L.length}</span><span><i>最高の 周回</i>${P.clear[5]||0}周目 クリア</span><span><i>ジョブ</i>${JOB_KEYS.filter(jobOpen).length} / ${JOB_KEYS.length}</span><span><i>マスター</i>${mastersCount()} / ${MAIN_JOBS.length}</span></div>
    <div class="bar" style="margin:4px 0 8px"><i style="background:var(--gold);transform:scaleX(${done/L.length})"></i></div>`;
  for(const c of cats){
    const xs = L.filter(x=>x.cat===c);
    h += `<h3>${c}（${xs.filter(x=>x.done).length}/${xs.length}）</h3><div class="list">`;
    // 未達成は 進んでいる順、達成は 下に
    xs.sort((a,b)=>(a.done-b.done) || (b.p.r-a.p.r));
    for(const x of xs) h += `<div class="li perk ${x.done?'done':''}" style="cursor:default"><div class="body">
      <div class="t"><span>${x.done?'✅':'🔒'} ${esc(veil(x.n))}</span><span class="hint">${x.done?'達成':Math.floor(x.p.r*100)+'%'}</span></div>
      <div class="d">${veil(x.d)}</div>
      ${x.done?'':`<div class="pbar"><i style="transform:scaleX(${x.p.r})"></i></div><div class="d hint">${veil(x.p.t)}</div>`}</div></div>`;
    h += `</div>`;
  }
  return h;
}

// ===== 目標（つぎに なにを めざすか。たっせいすると ほうび） =====
const gRef = n => [...Object.values(P.equip), ...P.inv].some(it => it && (it.ref||0) >= n);
const gMasters = () => JOB_KEYS.filter(k => jobLv(k) >= JOB_MAX).length;
const gJobAny = n => JOB_KEYS.some(k => jobLv(k) >= n);
const gClear = (st, rd) => (P.clear[st]||0) >= rd;
const gNum = (cur, need) => `${fmt(Math.min(cur, need))}/${fmt(need)}`;
// ネタバレを ふせる: まだ 見ていない ものは ？？？
const vStage = st => (st===0 || (P.clear[st-1]||0) >= 1 || (P.clear[st]||0) >= 1) ? STAGES[st].n : '？？？';
const vTower = () => towerOpen() ? '無限の塔' : '？？？';
const vArt = () => Object.keys(P.artFound||{}).length ? '神器' : '？？？';
const mkClear = (st, rd, extra='') => [`c${st}_${rd}`, () => `${rd>1?rd+'周目の ':''}${vStage(st)}を クリアする${typeof extra==='function'?extra():extra}`, () => gClear(st, rd)];
const mkTower = n => [`t${n}`, () => `${vTower()}で ${n}階に とどく`, () => towerPeak() >= n, () => gNum(towerPeak(), n)];
const v1000 = (s, alt='？？？') => towerPeak() >= 1000 ? s : alt;
const GOALS = [
  mkClear(0, 1, '（チュートリアル）'),
  ['spark1', 'ひらめき技を 1つ ひらめく', () => Object.keys(P.skills).some(k => SK[k] && SK[k].parent)],
  ['party', '仲間を パーティに 入れる', () => P.party.some(Boolean)],
  mkClear(1, 1),
  ['slots2', 'ひらめき技を 2つ セットする（スキルタブ）', () => P.slots.filter(Boolean).length >= 2],
  ['job5', 'ジョブを Lv5 に する', () => gJobAny(5)],
  ['ref3', '装備を +3 まで 精錬する（町の 精錬所）', () => gRef(3)],
  mkClear(3, 1),
  ['job2', 'べつの ジョブに ついてみる（ジョブタブ）', () => JOB_KEYS.filter(k => (P.jobs[k]||{}).jp > 0).length >= 2],
  mkClear(5, 1, () => (P.clear[4]||0) >= 1 ? '（1周目 クリア）' : ''),
  ['ally10', '仲間を 10体 あつめる', () => (P.stats.recruits||0) >= 10, () => gNum(P.stats.recruits||0, 10)],
  ['fuse', '仲間を 合体させる（仲間タブ）', () => P.allies.some(a => (a.plus||0) > 0)],
  ['card5', 'カードを 5まい 登録する', () => albumCount() >= 5, () => gNum(albumCount(), 5)],
  ['extract', 'ユニーク装備の 力を 抽出する', () => Object.keys(P.extracted||{}).length >= 1],
  mkClear(5, 3),
  ['master1', 'ジョブを 1つ マスターする', () => gMasters() >= 1],
  mkClear(5, CTRL_ROUND),
  ['combo3', () => allyCtrlOpen() ? 'かくし連携を 3つ 見つける（仲間も 操作）' : '？？？を 3つ 見つける', () => comboFound() >= 3, () => gNum(comboFound(), 3)],
  ['ref7', '装備を +7 まで 精錬する', () => gRef(7)],
  ['card20', 'カードを 20まい 登録する', () => albumCount() >= 20, () => gNum(albumCount(), 20)],
  mkClear(5, REF11_RD),
  ['master6', 'ジョブを 6つ マスターする', () => gMasters() >= 6, () => gNum(gMasters(), 6)],
  mkClear(5, TOWER_RD, () => (P.clear[5]||0) >= TOWER_RD-1 ? '（魔王を たおす）' : ''),
  mkTower(30),
  ['art1', () => `${vArt()}を 手に入れる`, () => Object.keys(P.artFound||{}).length >= 1],
  mkTower(50),
  mkClear(5, 15),
  ['ref11', () => refCap() >= 11 ? '装備を +11 まで 精錬する' : '装備を ？？？まで 精錬する', () => gRef(11)],
  mkTower(100),
  ['suppin', () => jobOpen('suppin') ? 'すっぴんに なる' : '？？？に なる（12の ジョブを マスター）', () => jobOpen('suppin')],
  ['cardAll', 'カード帖を コンプリートする', () => albumCount() >= Object.keys(CARDS).length, () => gNum(albumCount(), Object.keys(CARDS).length)],
  ['art7', () => `${vArt()}を 7本 そろえる`, () => artAll(), () => gNum(Object.keys(P.artFound||{}).length, 7)],
  mkClear(5, 20),
  mkTower(200),
  ['comboAll', () => allyCtrlOpen() ? 'かくし連携を すべて 見つける' : '？？？を すべて 見つける', () => comboFound() >= COMBOS.length, () => gNum(comboFound(), COMBOS.length)],
  mkTower(500),
  mkTower(1000),
  ['kiwami1', () => v1000('ひらめき技を 1つ 極める', '？？？'), () => Object.values(P.skills).some(s => stageOf(s.m) >= 5)],
  ['artUp3', () => v1000('神器を ✦3まで 強化する', '？？？'), () => Object.keys(ARTI).some(k => artLv(k) >= 3)],
  mkTower(1500),
  mkTower(2000),
  ['kiwami10', () => v1000('ひらめき技を 10個 極める', '？？？'), () => Object.values(P.skills).filter(s => stageOf(s.m) >= 5).length >= 10, () => gNum(Object.values(P.skills).filter(s => stageOf(s.m) >= 5).length, 10)],
  ['artUpMax', () => v1000('神器を ✦10まで 強化する', '？？？'), () => Object.keys(ARTI).some(k => artLv(k) >= ART_MAX)],
  mkTower(3000),
  mkTower(5000),
];
const goalText = g => typeof g[1] === 'function' ? g[1]() : g[1];
function goalReward(i){ const L = maxLReached(); return {gold: Math.round(eGold(L) * 40 * (1 + i/4)), boxes: 1 + Math.floor(i/8)}; }
const goalsDone = () => GOALS.filter(g => (P.goals||{})[g[0]]).length;
function goalsShown(){ P.goals = P.goals || {}; return GOALS.map((g,i)=>({g,i})).filter(o => !P.goals[o.g[0]]).slice(0, 3); }
const goalsReady = () => goalsShown().filter(o => o.g[2]()).length;
function panelGoals(){
  const list = goalsShown(), done = goalsDone();
  const head = `<h3>目標（${done}／${GOALS.length}）</h3><div class="row" style="margin:-4px 0 6px"><button class="btn sm" data-act="goalList">目標の 一覧を 見る</button></div>`;
  if(!list.length) return head + `<p class="hint">すべての 目標を たっせいした！</p>`;
  return head + `<div class="list">` + list.map(({g,i}) => {
    const ok = g[2](), rw = goalReward(i), prog = !ok && g[3] ? `<span class="hint">${g[3]()}</span>` : '';
    return `<div class="li ${ok?'':'locked'}" style="cursor:default;align-items:center"><div class="body"><div class="t"><span>${ok?'<span class="r2">★</span> ':''}${goalText(g)}</span>${prog}</div>
      <div class="d">ほうび：${fmt(rw.gold)}G ＋ 青箱 ${rw.boxes}こ</div></div>${ok?`<button class="btn sm primary" data-act="goalGet" data-k="${g[0]}" style="flex:none">うけとる</button>`:''}</div>`;
  }).join('') + `</div>`;
}
function showGoalList(){
  P.goals = P.goals || {};
  const rows = GOALS.map((g,i) => {
    const got = P.goals[g[0]], ok = !got && g[2](), rw = goalReward(i), prog = !got && !ok && g[3] ? `　${g[3]()}` : '';
    const mark = got ? '<span class="r4">✓</span>' : ok ? '<span class="r2">★</span>' : '<span class="hint">・</span>';
    return `<div style="display:flex;align-items:center;gap:6px;padding:5px 0;border-bottom:1px solid var(--line)">
      <span style="flex:none;width:1.2em;text-align:center">${mark}</span>
      <span style="flex:1;${got?'color:var(--dim)':''}">${goalText(g)}<span class="hint">${prog}</span><br><span class="hint">ほうび：${fmt(rw.gold)}G ＋ 青箱 ${rw.boxes}こ</span></span>
      ${ok?`<button class="btn sm primary" data-m="goalGetM" data-k="${g[0]}" style="flex:none">うけとる</button>`:''}</div>`;
  }).join('');
  showModal(`<h2>目標の 一覧（${goalsDone()}／${GOALS.length}）</h2><p class="hint">✓ うけとりずみ ／ ★ たっせい ／ ・ まだ</p>
    <div style="max-height:55vh;overflow-y:auto;font-size:13px">${rows}</div>
    <div class="opts"><button class="btn primary" data-m="close">とじる</button></div>`);
}
function claimGoal(k){
  const i = GOALS.findIndex(g => g[0]===k); if(i < 0 || (P.goals||{})[k] || !GOALS[i][2]()) return null;
  const rw = goalReward(i); P.goals[k] = true; P.gold += rw.gold; P.boxes = (P.boxes||0) + rw.boxes;
  try{ SFX.spark(); }catch(_){}
  save(); return rw;
}
// 出撃から もどったとき、新しく たっせいした 目標を 結果に 出す
function goalNews(){
  P.goalSeen = P.goalSeen || {}; const out = [];
  for(const {g} of goalsShown()) if(!P.goalSeen[g[0]] && g[2]()){ P.goalSeen[g[0]] = true; out.push(goalText(g)); }
  return out;
}
$('#panel').addEventListener('click', ev=>{
  const b = ev.target.closest('[data-act]'); if(!b) return;
  if(b.dataset.act==='goalList') showGoalList();
  else if(b.dataset.act==='goalGet'){ const rw = claimGoal(b.dataset.k); if(rw){ renderCamp(); showModal(`<h2>目標 たっせい！</h2><p>${fmt(rw.gold)}G と 青箱 ${rw.boxes}こ を 手に入れた。</p><p class="hint">青箱は カードタブで あけられる。</p><div class="opts"><button class="btn primary" data-m="close">OK</button></div>`); } }
});
$('#modal').addEventListener('click', ev=>{
  const b = ev.target.closest('[data-m="goalGetM"]'); if(!b) return;
  if(claimGoal(b.dataset.k)){ renderCamp(); showGoalList(); }
});

// ===== エンディング（10周目の 魔界で 魔王を たおしたとき。特典ページから 見なおせる） =====
function endingMusic(){
  if(typeof BGM_SRC!=='undefined' && BGM_SRC.ending && bgmOn()) return;   // 曲が あるときは そちらを 流す
  try{
    audioInit();
    const N = [523,659,784,1047, 988,784,880,1047, 1175,1047,988,880, 784,880,988,1047];
    N.forEach((f,k)=>tone(f, f, .26, 'square', .11, k*.28));
    [262,330,392,523].forEach((f,k)=>tone(f, f, 1.1, 'triangle', .08, k*1.12));
    [1047,1319,1568,2093].forEach((f,k)=>tone(f, f, .5, 'square', .1, 4.6+k*.12));
  }catch(_){}
}
function endingHtml(){
  const sp = (k, w=40, st='') => imgTag(k, '', `width:${w}px;height:auto;image-rendering:pixelated;${st}`);
  const party = members();
  const mons = Object.keys(P.album||{}).filter(k=>EDEF[k]);
  const skills = Object.keys(P.skills||{}).filter(k=>SK[k]);
  const masters = JOB_KEYS.filter(k=>jobLv(k) >= JOB_MAX);
  const line = (a, b) => `<div class="er"><span>${a}</span><b>${b}</b></div>`;
  return `
  <div class="ed-roll">
    <div class="ed-gap"></div>
    <h1>ピコーン・クエスト2</h1>
    <p class="ed-sub">〜 たびの きろく 〜</p>
    <div class="ed-gap s"></div>
    <h2>ゆうしゃ</h2>
    <div class="ed-hero">${sp(heroSpr(), 56)}</div>
    ${line('ジョブ', JOBS[P.job].n)}${line('レベル', 'Lv'+P.hero.lv)}
    ${masters.length ? `<p class="ed-cap">マスターした ジョブ（${masters.length}）</p><p class="ed-list">${masters.map(k=>JOBS[k].n).join('　')}</p>` : ''}
    <h2>ともに 戦った 仲間</h2>
    <div class="ed-party">${party.length ? party.map(al=>`<div>${sp(al.sp, 48)}<br>${esc(allyName(al))}<br><span>Lv${al.lv}</span></div>`).join('') : '<p>ひとりで 魔王を たおした！</p>'}</div>
    ${line('あつまった 仲間', (P.allies||[]).length+'体')}
    <h2>ひらめいた 技</h2>
    <p class="ed-list">${skills.map(k=>SK[k].n).join('　')}</p>
    <h2>出会った 魔物たち</h2>
    <div class="ed-mons">${mons.map(k=>`<span>${sp(k, 32)}</span>`).join('')}</div>
    <h2>きろく</h2>
    ${line('たおした 魔物', fmt(P.stats.kills||0)+'体')}${line('出撃', fmt(P.stats.runs||0)+'回')}${line('クリア', fmt(P.stats.clears||0)+'回')}
    <div class="ed-gap s"></div>
    <h2>つくった人</h2>
    <p class="ed-big">u1908inter</p>
    <p class="ed-list" style="color:#aaa">ゲームデザイン・ドット絵・プログラム・音楽（AI作曲）</p>
    <div class="ed-gap s"></div>
    <h2>Special Thanks</h2>
    <p class="ed-big">ここまで あそんでくれた あなた</p>
    <div class="ed-gap"></div>
    <p class="ed-end">THE END</p>
    <div class="ed-gap s"></div>
  </div>`;
}
function playEnding(done){
  let el = document.getElementById('ending');
  if(!el){ el = document.createElement('div'); el.id = 'ending'; document.body.appendChild(el); }
  const party = [heroSpr(), ...members().map(a=>a.sp)];
  el.innerHTML = `<div class="ed-story"></div><div class="ed-scroll" hidden></div>
    <div class="ed-walk" hidden>${party.map((k,i)=>`<span style="animation-delay:${-i*.18}s">${imgTag(k,'','width:36px;height:auto;image-rendering:pixelated')}</span>`).join('')}</div>
    <div class="ed-after" hidden></div>
    <button class="ed-skip">スキップ ▶▶</button>`;
  el.hidden = false; el.className = 'on';
  const story = el.querySelector('.ed-story'), scroll = el.querySelector('.ed-scroll'), walk = el.querySelector('.ed-walk'), after = el.querySelector('.ed-after');
  const T = []; const at = (ms, fn) => T.push(setTimeout(fn, ms));
  let fin = false;
  const finish = () => {
    if(fin) return; fin = true; T.forEach(clearTimeout);
    story.hidden = true; scroll.hidden = true; walk.hidden = true; after.hidden = false; el.querySelector('.ed-skip').hidden = true;
    after.innerHTML = `<p class="ed-end">THE END</p>
      <p class="ed-teaser">…しかし、魔界の 奥に<br>天まで とどく 塔が そびえていた。</p>
      <p class="r5 ed-big">無限の塔が ひらいた！</p>
      <div class="row" style="justify-content:center;gap:8px"><button class="btn" data-share="ending">𝕏 シェア</button><button class="btn primary" id="edClose">拠点へ もどる</button></div>`;
    after.querySelector('#edClose').onclick = () => { el.hidden = true; el.className = ''; el.innerHTML = ''; done && done(); };
  };
  el.querySelector('.ed-skip').onclick = finish;
  const lines = ['魔王は たおれた…', '魔界に 光が もどり、', 'ゆうしゃと 仲間たちは 長い 旅を おえた。', `ひらめいた 技は ${Object.keys(P.skills).length}つ、たおした 魔物は ${fmt(P.stats.kills||0)}体。`, 'これは、その たびの きろく。'];
  lines.forEach((t,i)=>at(800 + i*2300, ()=>{ const p = document.createElement('p'); p.textContent = t; story.appendChild(p); }));
  const t0 = 800 + lines.length*2300 + 1200;
  at(t0, ()=>{ story.classList.add('out'); });
  at(t0+900, ()=>{ story.hidden = true; scroll.hidden = false; walk.hidden = false; scroll.innerHTML = endingHtml(); endingMusic();
    const roll = scroll.querySelector('.ed-roll'); const h = roll.scrollHeight, dur = Math.max(24, Math.min(50, h/40));
    roll.animate([{transform:`translateY(${scroll.clientHeight}px)`},{transform:`translateY(${-h + scroll.clientHeight*0.45}px)`}], {duration:dur*1000, easing:'linear', fill:'forwards'});
    at(dur*1000 + 1500, finish); });
}

// ===== 拠点: たき火と テントを タップすると ちょっと うごく =====
const CF = {fire:0, tent:0, tentDir:1};
function drawTent(){
  const k = CF.tent, sw = k > 0 ? Math.sin(k*28)*k*3.2 : 0, sq = k > 0 ? Math.sin(k*20)*k*.12 : 0;   // ゆれと つぶれ
  const top = 60 + Math.round(sq*24), hgt = 84 - top;
  const row = (y, f) => { const p = y/hgt, off = Math.round(sw*(1-p)); f(off, p); };
  for(let y=0;y<hgt;y++) row(y, (off, p)=>{ const w=Math.round(p*24*1.2); ctx.fillStyle='#8a3a2a'; ctx.fillRect(162-w+off, top+y, w*2, 1);
    const w2=w-2; if(w2>0){ ctx.fillStyle='#c8553d'; ctx.fillRect(162-w+off, top+y, w2, 1); } });
  const door = 8 - Math.round(k*3);   // タップすると 入口が ひらく
  for(let y=Math.max(0,door);y<hgt;y++) row(y, (off, p)=>{ const w=Math.round((y-door)*(.5+k*.35)); ctx.fillStyle='#3a1a14'; ctx.fillRect(162-w+off, top+y, w*2+1, 1); });
  ctx.fillStyle='#5a3a22'; ctx.fillRect(161+Math.round(sw), top-3, 2, 4);
}
function campTap(ev){
  if(mode!=='camp') return;
  const r = cv.getBoundingClientRect(), x = (ev.clientX-r.left)/r.width*W, y = (ev.clientY-r.top)/r.height*H;
  if(x>98 && x<126 && y>74 && y<102){
    CF.fire = 1;
    for(let i=0;i<22;i++) PARTS.push({x:112+rand(-5,5), y:90+rand(-3,3), vx:rand(-22,22), vy:rand(-70,-30), life:rand(.5,1.1), max:1.1, col:pick(['#ffb04a','#ffe14a','#ff6a2a','#ffffff']), sz:Math.random()<.3?2:1, g:40});
    try{ audioInit(); for(let i=0;i<5;i++) tone(rand(180,420), 60, .05, 'sawtooth', .06, i*.06); tone(220, 660, .25, 'triangle', .07, .05); }catch(_){}
    try{ buzz(12); }catch(_){}
  }else if(x>128 && x<198 && y>52 && y<88){
    CF.tent = 1;
    for(let i=0;i<10;i++) PARTS.push({x:162+rand(-26,26), y:84, vx:rand(-14,14), vy:rand(-14,-4), life:.5, max:.5, col:'#d6c290', sz:1, g:20});
    try{ audioInit(); tone(330, 140, .18, 'square', .07); tone(520, 780, .08, 'triangle', .06, .14); }catch(_){}
    try{ buzz(10); }catch(_){}
  }
}
cv.addEventListener('pointerdown', campTap);

// ===== 初代と 同じ くらしの 機能: 留守のあいだの成果・お知らせ・セーブの まもり・Xで シェア =====
// --- 小さな お知らせ（トースト） ---
let _toastT = 0;
function toast(html){
  let c = document.getElementById('toast');
  if(!c){ c = document.createElement('div'); c.id = 'toast'; document.body.appendChild(c); }
  c.innerHTML = html; c.hidden = false; clearTimeout(_toastT); _toastT = setTimeout(()=>{ c.hidden = true; }, 2200);
}
// モーダルが あいていない ときに 出す
function whenFree(fn){ const t = setInterval(()=>{ if($('#modal').hidden && mode==='camp' && !document.getElementById('ending')?.className){ clearInterval(t); fn(); } }, 600); }

// --- タブの NEW 印 ---
function setNew(tab){ P.newMark = P.newMark || {}; if(P.newMark[tab]) return; P.newMark[tab] = true; if(mode==='camp') renderCamp(); }
function tabBadges(){
  P.newMark = P.newMark || {};
  if(mode==='camp' && P.newMark[TAB]) delete P.newMark[TAB];   // ひらいたら 消える
  for(const k of ['ally','gear','job','card','town']){
    const b = $(`#tabs [data-tab="${k}"]`); if(!b) continue;
    let bd = b.querySelector('.nb.nw'); const on = !!P.newMark[k];
    if(on && !bd){ bd = document.createElement('span'); bd.className = 'nb nw'; bd.textContent = 'NEW'; b.appendChild(bd); }
    else if(!on && bd) bd.remove();
  }
}
// ジョブの 解放を 知らせる
function jobUnlockCheck(silent){
  P.jobSeen = P.jobSeen || null;
  const open = JOB_KEYS.filter(k=>JOBS[k].unlock && jobOpen(k));
  if(!P.jobSeen){ P.jobSeen = {}; open.forEach(k=>P.jobSeen[k]=1); save(); return; }   // はじめは いまの 状態を 覚えるだけ
  const fresh = open.filter(k=>!P.jobSeen[k]); if(!fresh.length) return;
  fresh.forEach(k=>P.jobSeen[k]=1); save(); setNew('job');
  if(silent) return;
  whenFree(()=>{ try{ SFX.spark(); }catch(_){}
    showModal(`<h2 class="r2">新しい ジョブが 解放された！</h2><ul style="line-height:1.8">${fresh.map(k=>`<li><b>${JOBS[k].n}</b> ― ${JOBS[k].d}</li>`).join('')}</ul><p class="hint">ジョブタブで つける。</p><div class="opts"><button class="btn primary" data-m="close">OK</button></div>`); });
}

// --- 留守のあいだの成果（とじている あいだも 仲間が 戦う。最大 8時間） ---
const OFFLINE_MAX_H = 8, OFFLINE_KPH = 600;
function offlineStage(){
  const ls = P.lastStage; if(ls && (P.clear[ls.st]||0) >= ls.rd) return ls;   // さいごに クリアした ところ
  let best = null; for(let st=0; st<6; st++) if(P.clear[st]) { const rd = P.clear[st]; if(!best || lvOf(st,rd) > lvOf(best.st,best.rd)) best = {st, rd}; }
  return best;
}
function grantOffline(ms){
  if(ms < 60000 || !(P.clear[0] >= 1)) return null;
  const sg = offlineStage(); if(!sg) return null;
  refreshHS();
  const h = Math.min(OFFLINE_MAX_H, ms/3600000), L = lvOf(sg.st, sg.rd), kills = Math.floor(h*OFFLINE_KPH); if(kills < 1) return null;
  const exp = Math.round(kills * eExp(L) * (1+HS.exp/100)), gold = Math.round(kills * eGold(L) * (1+HS.gold/100));
  const mk = ST_MAT[sg.st], mats = Math.floor(kills * CFG.matRate * .5), boxes = Math.floor(kills * .003);
  P.gold += gold; P.mats[mk] = (P.mats[mk]||0) + mats; P.boxes = (P.boxes||0) + boxes;
  const lv0 = P.hero.lv; P.hero.exp += exp; while(P.hero.exp >= needExp(P.hero.lv)){ P.hero.exp -= needExp(P.hero.lv); P.hero.lv++; }
  allyGainExp(exp);
  P.stats.kills = (P.stats.kills||0) + kills;
  refreshHS();
  return {h, sg, kills, exp, gold, mk, mats, boxes, lvUp: P.hero.lv - lv0};
}
function showOffline(r){
  const hh = Math.floor(r.h), mm = Math.round((r.h-hh)*60);
  try{ SFX.spark(); }catch(_){}
  showModal(`<h2 class="r2" style="text-align:center">おかえりなさい！</h2>
    <p style="text-align:center">${hh ? hh+'時間' : ''}${mm}分の あいだ、仲間たちが ${STAGES[r.sg.st].n}（${r.sg.rd}周目）で がんばっていた。</p>
    <div class="kv"><span><i>たおした 魔物</i>${fmt(r.kills)}体</span><span><i>経験値</i>+${fmt(r.exp)}</span>
      <span><i>ゴールド</i>+${fmt(r.gold)}</span><span><i>${MATS[r.mk].n}</i>+${fmt(r.mats)}</span>
      ${r.boxes ? `<span><i>青箱</i>+${r.boxes}</span>` : ''}${r.lvUp ? `<span><i>ゆうしゃ</i>Lv +${r.lvUp}</span>` : ''}</div>
    <p class="hint" style="text-align:center">ゲームを とじている あいだも、最大 ${OFFLINE_MAX_H}時間ぶん 成果が たまる。</p>
    <div class="opts"><button class="btn primary" data-m="close">うけとる</button></div>`);
  if(mode==='camp'){ syncHero(); buildParty(); renderButtons(); renderCamp(); }
}
function checkOffline(){
  const now = Date.now(), last = P.lastActive || 0; P.lastActive = now;
  if(!last){ save(); return; }
  const r = grantOffline(now - last);
  save();
  if(r) whenFree(()=>showOffline(r));
}

// --- セーブの まもり ---
let _saveWarned = false, _lastSaveAt = 0;
function saveFailed(){ if(_saveWarned) return; _saveWarned = true; toast('<span style="color:#ffb0a6">セーブに 失敗した。設定の「書き出す」で バックアップしてね</span>'); }
function manualSave(){
  let ok = true;
  try{ saveNow(); ok = LS.get(SAVE_KEY) === JSON.stringify(P); }catch(e){ ok = false; }
  if(ok){ _lastSaveAt = Date.now(); toast('セーブした（'+new Date().toLocaleTimeString('ja-JP')+'）'); }
  else toast('<span style="color:#ffb0a6">セーブできなかった。「書き出す」で バックアップしてね</span>');
  if(mode==='camp') renderCamp();
}
const lastSaveText = () => (typeof lastSave!=='undefined' && lastSave) ? new Date(lastSave).toLocaleTimeString('ja-JP') : '―';
const BACKUP_AT = [{k:'r1', ok:()=>(P.clear[5]||0)>=1, t:'1周目の 魔界を クリアした'}, {k:'r3', ok:()=>(P.clear[5]||0)>=3, t:'3周目の 魔界を クリアした'},
  {k:'r5', ok:()=>(P.clear[5]||0)>=5, t:'5周目の 魔界を クリアした'}, {k:'r10', ok:()=>(P.clear[5]||0)>=10, t:'魔王を たおした'},
  {k:'t50', ok:()=>towerBest()>=50, t:'塔の 50階に とどいた'}, {k:'r20', ok:()=>(P.clear[5]||0)>=20, t:'20周目の 魔界を クリアした'}];
function backupTick(){
  if(mode!=='camp' || !$('#modal').hidden || P.debug) return;
  P.backupAsked = P.backupAsked || {};
  const hit = BACKUP_AT.filter(b=>b.ok() && !P.backupAsked[b.k]); if(!hit.length) return;
  hit.forEach(b=>P.backupAsked[b.k] = true); save();
  const b = hit[hit.length-1];
  showModal(`<h2 class="r2">セーブを まもろう</h2><p>${b.t}！ この ぼうけんの 記録は、この ブラウザの 中だけに ある。ブラウザの データを 消したり、べつの 端末で 遊んだりすると 続きから 遊べない。</p>
    <p>設定の「書き出す」で 文字に して とっておくと 安心。</p>
    <div class="opts"><button class="btn" data-m="close">あとで</button><button class="btn primary" data-m="backupNow">書き出す</button></div>`);
}
$('#modal').addEventListener('click', ev=>{ const b = ev.target.closest('[data-m="backupNow"]'); if(!b) return;
  hideModal(); TAB = 'cfg'; if(typeof CFGVIEW!=='undefined') CFGVIEW = 'cfg'; renderCamp(); const x = document.querySelector('[data-act="export"]'); if(x){ x.click(); x.scrollIntoView({block:'center'}); } });

// --- 記録を Xで シェア ---
const SITE_URL = 'https://u1908inter.github.io/pikon-quest2/';
function shareText(kind){
  const base = `ゆうしゃ Lv${fmt(P.hero.lv)}・仲間 ${(P.allies||[]).length}体`;
  if(kind==='ending') return `ピコーン・クエスト2で 魔王を たおした！（${base}）`;
  if(kind==='trueClear') return `ピコーン・クエスト2を 完全制覇した！（無限の塔 1000階 とっぱ／${base}／称号「${titleOf()}」）`;
  const rd = P.clear[5]||0, tw = towerPeak();
  return rd ? `ピコーン・クエスト2で ${rd}周目の 魔界を クリア！（${base}${tw ? `／無限の塔 ${tw}階${titleOf()?`・称号「${titleOf()}」`:''}` : ''}）` : `ピコーン・クエスト2を 遊んでいる！（${base}）`;
}
